# Generated by Claude Opus 5.5 with human oversight

#' Apply human in the loop flags and comments
#'
#' Applies flags and comments that a person assigned after reviewing the
#' automated quality control results.
#'
#' Flags are assigned to each observation of each variable. For example, if a
#' sensor measures dissolved oxygen and temperature at the same time, and only
#' the dissolved oxygen observation is poor quality, then only
#' \code{human_in_loop_flag_dissolved_oxygen_percent_saturation} will have a
#' value of 3 or 4 (as specified in \code{human_in_loop_table}), while
#' \code{human_in_loop_flag_temperature_degree_c} will be 1.
#'
#' However, there is only one column for comments, \code{hil_comment}. This is
#' to reduce the total number of columns in the wide data set. The trade off is
#' that the comment will appear to apply to both variables. To avoid confusion
#' in this situation, comments should be pre-pended with the variable they refer
#' to, e.g., "dissolved oxygen: suspected biofouling not flagged by other
#' tests". This is not necessary for comments that apply to all variables (e.g.,
#' only one variable is measured).
#'
#' When more than one row of \code{human_in_loop_table} applies to an
#' observation, the observation gets the highest flag, and the comments are
#' pasted together, separated by "; ".
#'
#' @param dat Data frame of flagged sensor string data in wide format, for one
#'   deployment.
#'
#' @param human_in_loop_table Data frame with one row for each set of
#'   observations to flag. Rows for other stations and deployments are ignored,
#'   so the whole table can be passed for every deployment. Columns:
#'
#'   * \code{station}, \code{deployment_range}: the deployment.
#'   * \code{variable}: the variable to flag. \code{NA} flags every variable.
#'   * \code{sensor_serial_number}: the sensor to flag. \code{NA} flags every
#'   sensor.
#'   * \code{timestamp_utc_min}, \code{timestamp_utc_max}: observations from
#'   \code{timestamp_utc_min} to \code{timestamp_utc_max} (inclusive) are
#'   flagged. \code{NA} means the start or end of the deployment. To flag the
#'   observations outside a window, use two rows: one with
#'   \code{timestamp_utc_min = NA}, and one with \code{timestamp_utc_max = NA}.
#'   * \code{qc_test}, \code{qc_flag_value} (optional): only flag observations
#'   where \code{qc_test} (e.g., "rolling_sd") gave flag \code{qc_flag_value}.
#'   \code{NA} in either column, or no columns, means any flag.
#'   * \code{human_in_loop_flag_value}: the flag to assign (1 to 4).
#'   * \code{hil_comment}: the comment to include in the data.
#'
#' @return Returns \code{dat} with a \code{human_in_loop_flag_<variable>} column
#'   for each variable and a \code{hil_comment} column. Observations not flagged
#'   by \code{human_in_loop_table} get flag 1 and comment \code{NA}. If no rows
#'   of \code{human_in_loop_table} are for the deployment in \code{dat},
#'   \code{dat} is returned unchanged.
#'
#' @importFrom dplyr across all_of any_of contains distinct filter left_join mutate rename_with row_number select
#' @importFrom tidyr pivot_wider
#'
#' @export

qc_test_human_in_loop <- function(
  dat,
  human_in_loop_table = NULL
) {
  # checks ------------------------------------------------------------------

  if (length(unique(dat$station)) > 1 ||
    length(unique(dat$deployment_range)) > 1) {
    stop("more than one deployment found in << dat >>", call. = FALSE)
  }

  if (any(grepl("^human_in_loop_flag_", colnames(dat)))) {
    stop(
      "<< dat >> already has human in the loop flags. ",
      "Put all the rows for this deployment in one << human_in_loop_table >>.",
      call. = FALSE
    )
  }

  if (is.null(human_in_loop_table)) {
    message("human-in-loop table is NULL. No flags applied")
    return(dat)
  }

  required_cols <- c(
    "station",
    "deployment_range",
    "variable",
    "sensor_serial_number",
    "timestamp_utc_min",
    "timestamp_utc_max",
    "human_in_loop_flag_value",
    "hil_comment"
  )
  missing_cols <- setdiff(required_cols, colnames(human_in_loop_table))
  if (length(missing_cols) > 0) {
    stop(
      "<< human_in_loop_table >> is missing column(s): ",
      paste(missing_cols, collapse = ", "),
      call. = FALSE
    )
  }

  # rows for this deployment only -------------------------------------------

  hil <- human_in_loop_table |>
    filter(
      station == unique(dat$station),
      deployment_range == unique(dat$deployment_range)
    ) |>
    mutate(hil_row = row_number())

  if (nrow(hil) == 0) {
    message(
      "no human in the loop flags to apply for << ",
      unique(dat$station), " ", unique(dat$deployment_range), " >>"
    )
    return(dat)
  }

  # the reference flag columns are optional
  if (!("qc_test" %in% colnames(hil))) {
    hil <- mutate(hil, qc_test = NA_character_)
  }
  if (!("qc_flag_value" %in% colnames(hil))) {
    hil <- mutate(hil, qc_flag_value = NA_real_)
  }

  if (!all(hil$human_in_loop_flag_value %in% 1:4)) {
    stop("<< human_in_loop_flag_value >> must be 1, 2, 3 or 4.", call. = FALSE)
  }
  if (any(hil$timestamp_utc_min > hil$timestamp_utc_max, na.rm = TRUE)) {
    stop(
      "<< timestamp_utc_min >> is after << timestamp_utc_max >> in ",
      "<< human_in_loop_table >>.",
      call. = FALSE
    )
  }
  if (any(!is.na(hil$qc_flag_value) & is.na(hil$qc_test))) {
    stop(
      "<< qc_flag_value >> is given without << qc_test >> in ",
      "<< human_in_loop_table >>.",
      call. = FALSE
    )
  }

  # automated test flags in dat, for the qc_test / qc_flag_value condition
  test_pattern <- "^(climatology|grossrange|rolling_sd|spike)_flag_(.+)$"
  dat_tests <- unique(
    sub(test_pattern, "\\1", grep(test_pattern, colnames(dat), value = TRUE))
  )

  # only tests with a qc_flag_value are used
  ref_tests <- unique(hil$qc_test[!is.na(hil$qc_flag_value)])

  missing_tests <- setdiff(ref_tests, dat_tests)
  if (length(missing_tests) > 0) {
    stop(
      "<< dat >> has no flags for << qc_test >>: ",
      paste(missing_tests, collapse = ", "),
      call. = FALSE
    )
  }

  # apply in long format --------------------------------------------------------

  dat <- mutate(dat, row_id = row_number())

  # one row per observation and variable, with a <qc_test>_flag column for each
  # test in ref_tests
  ref_flag_cols <- grep(
    paste0("^(", paste(ref_tests, collapse = "|"), ")_flag_"),
    colnames(dat),
    value = TRUE
  )

  dat_long <- dat |>
    select(
      -any_of("hil_comment"),
      -(contains("flag") & !all_of(ref_flag_cols))
    ) |>
    qc_pivot_longer(qc_tests = ref_tests) |>
    rename_with(~ sub("_flag_value$", "_flag", .x)) |>
    mutate(across(
      any_of(paste0(ref_tests, "_flag")),
      ~ as.integer(as.character(.x))
    )) |>
    qc_core_human_in_loop(hil)

  # back to wide ---------------------------------------------------------------

  flags_wide <- dat_long |>
    select(row_id, variable, human_in_loop_flag) |>
    pivot_wider(
      names_from = variable,
      values_from = human_in_loop_flag,
      names_prefix = "human_in_loop_flag_"
    ) |>
    mutate(across(-row_id, ~ ordered(.x, levels = 1:4)))

  hil_comments <- distinct(dat_long, row_id, hil_comment)

  dat |>
    select(-any_of("hil_comment")) |>
    left_join(flags_wide, by = "row_id") |>
    left_join(hil_comments, by = "row_id") |>
    select(-row_id)
}
